INSERT INTO sources VALUES ('src_udm_master','Universal Decoding Matrix — Master Workbook','SME Pro Technologies','iosmcp.com','Internal master reference; verify with official concordances for regulatory/statistical use','2026-07-27');
INSERT INTO sources VALUES ('src_00','NAICS 2022','U.S. Census Bureau NAICS official page','https://www.census.gov/naics/','NAICS is the standard used by U.S. federal statistical agencies; this workbook uses 2022 sectors/subsectors as the NAICS bridge.','2026-07-27');
INSERT INTO sources VALUES ('src_01','ISIC Rev.4','United Nations Statistics Division ISIC Rev.4 PDF','https://unstats.un.org/unsd/demographic-social/census/documents/isic_rev4.pdf','ISIC Rev.4 divisions are the global anchor because ISIC classifies all economic activities internationally.','2026-07-27');
INSERT INTO sources VALUES ('src_02','GICS','S&P Dow Jones Indices GICS overview','https://www.spglobal.com/spdji/en/landing/topic/gics/','GICS has 11 sectors, 25 industry groups, 74 industries, and 163 sub-industries for company/investment analysis.','2026-07-27');
INSERT INTO sources VALUES ('src_03','GICS Methodology','MSCI GICS methodology 2023','https://www.msci.com/documents/1296102/11185224/GICS+Methodology+2023.pdf','Used for GICS hierarchy, global scope, annual review, and classification principles.','2026-07-27');
INSERT INTO sources VALUES ('src_04','Coverage note','Ontology crosswalk design','This workbook','This is an ontological bridge, not a legal one-to-one concordance. Some government, household, nonprofit, and supranational activities sit outside GICS.','2026-07-27');
INSERT INTO sources VALUES ('src_05','GICS full hierarchy','S&P Dow Jones Indices GICS overview','https://www.spglobal.com/spdji/en/landing/topic/gics/','S&P states the current GICS structure consists of 11 sectors, 25 industry groups, 74 industries, and 163 sub-industries.','2026-07-27');
INSERT INTO sources VALUES ('src_06','ISIC full hierarchy','United Nations Statistics Division ISIC Rev.4','https://unstats.un.org/unsd/classifications/Econ/','ISIC Rev.4 hierarchy includes 21 sections, 88 divisions, 238 groups, and 419 classes.','2026-07-27');
INSERT INTO sources VALUES ('src_07','SOC 2018','U.S. Bureau of Labor Statistics SOC official page','https://www.bls.gov/soc/','SOC classifies workers into occupational categories; it is not an industry taxonomy.','2026-07-27');
INSERT INTO sources VALUES ('src_08','CIP 2020','NCES Classification of Instructional Programs','https://nces.ed.gov/ipeds/cipcode/default.aspx?y=55','CIP classifies instructional programs/fields of study; it maps to SOC, not directly to industry codes.','2026-07-27');
INSERT INTO sources VALUES ('src_09','NAICS/SIC concordances','U.S. Census Bureau NAICS concordances','https://www.census.gov/naics/concordances/concordances.html','Use official concordances for SIC ⇄ NAICS and international industry-code bridge work.','2026-07-27');
INSERT INTO sources VALUES ('src_10','GEOID/FIPS/GNIS','U.S. Census Bureau Understanding Geographic Identifiers','https://www.census.gov/programs-surveys/geography/guidance/geo-identifiers.html','Geographic identifiers uniquely identify administrative/legal and statistical geographies; use them as the jurisdiction key.','2026-07-27');
INSERT INTO sources VALUES ('src_11','State/local governments','USAGov State and local governments','https://www.usa.gov/state-local-governments','Use official state/local agency sources for governing entity names and contact points.','2026-07-27');
INSERT INTO sources VALUES ('src_12','Federal agencies','USAGov A-Z index of federal agencies','https://www.usa.gov/agency-index','Use official federal agency records to identify national regulators, funders, and program owners.','2026-07-27');
INSERT INTO sources VALUES ('src_13','CIP-SOC Crosswalk','NCES CIP-SOC Crosswalk','https://nces.ed.gov/ipeds/cipcode/post3.aspx?y=56','Official NCES/BLS crosswalk maps 2020 6-digit CIP codes to 2018 6-digit SOC codes by content/expert judgment, not empirical outcomes data.','2026-07-27');
INSERT INTO sources VALUES ('src_14','IPEDS institution data','NCES IPEDS','https://nces.ed.gov/ipeds/Search','IPEDS is the core NCES postsecondary data collection system for institution-level enrollments, completions, staff, finance, and related data.','2026-07-27');
INSERT INTO sources VALUES ('src_15','SOC-by-industry employment','BLS OEWS industry-specific occupational employment','https://www.bls.gov/oes/current/oessrci.htm','Use OEWS to relate SOC occupations to NAICS industries through employment and wage data.','2026-07-27');
INSERT INTO sources VALUES ('src_16','Screenshot UDM pattern','Attached apppic.png','apppic.png','Used to model header tags, navigation tabs, orchestrator routing, server manifest, detected entities, and feature families into the Universal Decoding Matrix.','2026-07-27');
INSERT INTO sources VALUES ('src_reg_matrix','Oil & Gas Agency Reporting Requirements Matrix','SME Pro Technologies (compiled from official agency pages)','iosmcp.com','Agency-by-agency reporting matrix; each row carries the official agency source URL','2026-07-27');
