INSERT INTO regulatory_bodies VALUES ('body_rrc','RRC','Railroad Commission of Texas','jur_texas','RRC Online; EDI for production; PDF/Excel/Word forms where not online','Strong online filing; long form catalog; monthly production/transport and detailed W-series well lifecycle forms; RRC form versions and online availability matter.','https://www.rrc.texas.gov/oil-and-gas/oil-and-gas-forms/');
INSERT INTO authority_scopes VALUES ('scope_00','body_rrc','oil_gas','Strong online filing; long form catalog; monthly production/transport and detailed W-series well lifecycle forms; RRC form versions and online availability matter.');
INSERT INTO regulatory_bodies VALUES ('body_occ','OCC','Oklahoma Corporation Commission Oil & Gas Conservation Division','jur_oklahoma','OCC forms/e-filing plus downloadable PDF forms','Uses state-specific OCC forms and paper/electronic workflows; confirm whether each form is available online before filing.','https://oklahoma.gov/occ/divisions/oil-gas/ogcd-forms/ogcd-paper-forms.html');
INSERT INTO authority_scopes VALUES ('scope_01','body_occ','oil_gas','Uses state-specific OCC forms and paper/electronic workflows; confirm whether each form is available online before filing.');
INSERT INTO regulatory_bodies VALUES ('body_ldnr','LDNR','Louisiana Office of Conservation / DENR','jur_louisiana','Office of Conservation engineering forms and SONRIS-related reporting','Engineering/conservation forms; Louisiana uses parish/field/unit context and separate conservation reporting workflows.','https://www.denr.louisiana.gov/page/con-forms-engineering-division');
INSERT INTO authority_scopes VALUES ('scope_02','body_ldnr','oil_gas','Engineering/conservation forms; Louisiana uses parish/field/unit context and separate conservation reporting workflows.');
INSERT INTO regulatory_bodies VALUES ('body_ocd','OCD','New Mexico Oil Conservation Division','jur_newmexico','OCD Online / Excel templates / PDFs','Production reporting uses C-115 Excel template or custom compatible system; state-specific OCD forms and nightly statistics/reports.','https://www.emnrd.nm.gov/ocd/wp-content/uploads/sites/6/C-115-INSTRUCTIONS.pdf');
INSERT INTO authority_scopes VALUES ('scope_03','body_ocd','oil_gas','Production reporting uses C-115 Excel template or custom compatible system; state-specific OCD forms and nightly statistics/reports.');
INSERT INTO regulatory_bodies VALUES ('body_ecmc','ECMC','Colorado Energy & Carbon Management Commission','jur_colorado','ECMC eForms, Webforms, online forms, PDFs','Very form-number driven; development approvals use Form 2/2A/2B/2C; Form 7 monthly operations; many forms explicitly eForms vs Webforms.','https://ecmc.colorado.gov/forms-and-operator-guidance/forms');
INSERT INTO authority_scopes VALUES ('scope_04','body_ecmc','oil_gas','Very form-number driven; development approvals use Form 2/2A/2B/2C; Form 7 monthly operations; many forms explicitly eForms vs Webforms.');
INSERT INTO regulatory_bodies VALUES ('body_wogcc','WOGCC','Wyoming Oil and Gas Conservation Commission','jur_wyoming','Wyoming eForm, WYSTAR, WYDE/data explorer','Electronic forms and WYSTAR rig schedule; completion Form 3 due under Wyoming rules; directional survey and rig schedule tools are unique workflow items.','https://wogcc.wyo.gov/electronic-forms');
INSERT INTO authority_scopes VALUES ('scope_05','body_wogcc','oil_gas','Electronic forms and WYSTAR rig schedule; completion Form 3 due under Wyoming rules; directional survey and rig schedule tools are unique workflow items.');
INSERT INTO regulatory_bodies VALUES ('body_ndic','NDIC','ND Industrial Commission Oil & Gas Division','jur_northdakota','NorthSTAR; ND Electronic Filing; hardcopy for some forms; Excel-to-XML for some monthly reports','Clear submission-process column by form: APD/completion/plugging through NorthSTAR; production through Electronic Filing; some hardcopy remains.','https://www.dmr.nd.gov/oilgas/rules/fillinforms.asp');
INSERT INTO authority_scopes VALUES ('scope_06','body_ndic','oil_gas','Clear submission-process column by form: APD/completion/plugging through NorthSTAR; production through Electronic Filing; some hardcopy remains.');
INSERT INTO regulatory_bodies VALUES ('body_calgem','CalGEM','California Geologic Energy Management Division','jur_california','CalGEM forms; electronic submission where available','Oil/gas operators submit well data and forms to CalGEM; California separates many operational and environmental reporting forms.','https://conservation.ca.gov/calgem/pubs_stats/Pages/forms.aspx');
INSERT INTO authority_scopes VALUES ('scope_07','body_calgem','oil_gas','Oil/gas operators submit well data and forms to CalGEM; California separates many operational and environmental reporting forms.');
INSERT INTO regulatory_bodies VALUES ('body_aogcc','AOGCC','Alaska Oil & Gas Conservation Commission','jur_alaska','PDF/Excel forms; permit docs by PDF email; EDI for production/injection','10-401/403/404/407 with docs must be digital PDF by email; 10-405/10-406 have EDI file instructions.','https://www.commerce.alaska.gov/web/aogcc/Forms.aspx');
INSERT INTO authority_scopes VALUES ('scope_08','body_aogcc','oil_gas','10-401/403/404/407 with docs must be digital PDF by email; 10-405/10-406 have EDI file instructions.');
INSERT INTO regulatory_bodies VALUES ('body_kcc','KCC','Kansas Corporation Commission Conservation Division','jur_kansas','KOLAR online reporting; PDF fill-ins mostly residential only','KOLAR required for non-residential operations where form is available; annual UIC U3-C due March 1.','https://www.kcc.ks.gov/oil-gas/oil-gas-forms');
INSERT INTO authority_scopes VALUES ('scope_09','body_kcc','oil_gas','KOLAR required for non-residential operations where form is available; annual UIC U3-C due March 1.');
INSERT INTO regulatory_bodies VALUES ('body_padep','PA DEP','PA DEP Office of Oil and Gas Management','jur_pennsylvania','GreenPort, OGRE, eWELL/eSubmission, PDFs/Excel where specified','Separate conventional/unconventional workflows; OGRE handles SPUD, notifications, production/waste, Act 9, MIA.','https://www.pa.gov/agencies/dep/programs-and-services/oil-and-gas/electronic-submission-guides');
INSERT INTO authority_scopes VALUES ('scope_10','body_padep','oil_gas','Separate conventional/unconventional workflows; OGRE handles SPUD, notifications, production/waste, Act 9, MIA.');
INSERT INTO regulatory_bodies VALUES ('body_odnr','ODNR','Ohio Department of Natural Resources DOGRM','jur_ohio','ODNR forms; email/electronic production; horizontal quarterly reporting','Horizontal production quarterly; vertical/conventional annual Form 10 by Mar 31; Form 10 requires 14-digit API without dashes.','https://ohiodnr.gov/wps/portal/gov/odnr/business-and-industry/energy-resources/well-information/production');
INSERT INTO authority_scopes VALUES ('scope_11','body_odnr','oil_gas','Horizontal production quarterly; vertical/conventional annual Form 10 by Mar 31; Form 10 requires 14-digit API without dashes.');
INSERT INTO regulatory_bodies VALUES ('body_wvdep','WVDEP','WVDEP Office of Oil and Gas','jur_westvirginia','WVDEP forms; WR-39/WR-39E production; permit packets','Uses WR-series and WW/OP forms; annual data and horizontal H6A datasets separate from general forms.','https://dep.wv.gov/oil-and-gas/GI/Forms/Pages/default.aspx');
INSERT INTO authority_scopes VALUES ('scope_12','body_wvdep','oil_gas','Uses WR-series and WW/OP forms; annual data and horizontal H6A datasets separate from general forms.');
INSERT INTO regulatory_bodies VALUES ('body_dogm','DOGM','Utah Division of Oil, Gas and Mining','jur_utah','ePermit; eForm; PDF/Excel templates','ePermit for APD, sundry, completion, logs; eForm for monthly production/disposition/gas plant/injection; Form 10 monthly production.','https://ogm.utah.gov/electronic-reporting/');
INSERT INTO authority_scopes VALUES ('scope_13','body_dogm','oil_gas','ePermit for APD, sundry, completion, logs; eForm for monthly production/disposition/gas plant/injection; Form 10 monthly production.');
INSERT INTO regulatory_bodies VALUES ('body_mbogc','MBOGC','Montana Board of Oil and Gas Conservation','jur_montana','Online Data/DataMiner plus PDF forms/reports','Board collects well/production data and provides online data exports; Form 6 production report is monthly and due by 25th after production month per available instruction source.','https://bogapps.dnrc.mt.gov/dataminer/Default.aspx');
INSERT INTO authority_scopes VALUES ('scope_14','body_mbogc','oil_gas','Board collects well/production data and provides online data exports; Form 6 production report is monthly and due by 25th after production month per available instruction source.');
INSERT INTO regulatory_bodies VALUES ('body_aogc','AOGC','Arkansas Oil and Gas Commission','jur_arkansas','AOGC online services/payment; forms/rules pages','Issues permits to drill, operate, produce, plug; regulates seismic, E&P fluids and gas pipelines; detailed form list must be confirmed on AOGC forms/rules site.','https://ee.arkansas.gov/energy/oil-gas-commission/');
INSERT INTO authority_scopes VALUES ('scope_15','body_aogc','oil_gas','Issues permits to drill, operate, produce, plug; regulates seismic, E&P fluids and gas pipelines; detailed form list must be confirmed on AOGC forms/rules site.');
INSERT INTO regulatory_bodies VALUES ('body_msogb','MSOGB','Mississippi State Oil and Gas Board','jur_mississippi','MSOGB site/data explorer; board forms may require direct site access/contact','Official public snippets expose mission/contact but not full form catalog; verify latest forms directly with MSOGB before filing.','https://www.ogb.state.ms.us/');
INSERT INTO authority_scopes VALUES ('scope_16','body_msogb','oil_gas','Official public snippets expose mission/contact but not full form catalog; verify latest forms directly with MSOGB before filing.');
INSERT INTO regulatory_bodies VALUES ('body_egle','EGLE','Michigan EGLE Geologic Resources Management Division','jur_michigan','MiSTAR mandatory for production/injection; email for many forms; permits through MiSTAR','Most required production/injection reports through MiSTAR; logs in LAS/TIF; file-size and naming rules are explicit.','https://www.michigan.gov/egle/about/organization/geologic-resources-management/oil-and-gas/forms');
INSERT INTO authority_scopes VALUES ('scope_17','body_egle','oil_gas','Most required production/injection reports through MiSTAR; logs in LAS/TIF; file-size and naming rules are explicit.');
INSERT INTO regulatory_bodies VALUES ('body_idnr','IDNR','Illinois DNR Office of Oil and Gas Resource Management','jur_illinois','Mail hardcopy for most; selected UIC applications accepted by email','OG-10/OG-03 permit workflow; OG-09 completion; OG-15 TA; OG-18 annual Class II; some applications email to DNR.OOGRMApps, others mail.','https://dnr.illinois.gov/oilandgas/formslistslogs.html');
INSERT INTO authority_scopes VALUES ('scope_18','body_idnr','oil_gas','OG-10/OG-03 permit workflow; OG-09 completion; OG-15 TA; OG-18 annual Class II; some applications email to DNR.OOGRMApps, others mail.');
INSERT INTO regulatory_bodies VALUES ('body_nogcc','NOGCC','Nebraska Oil and Gas Conservation Commission','jur_nebraska','eReports for production/injection/disposal; PDF/online forms; Data Mining','eReports site handles Production, Injection, Disposal; registration activation required; historic data through GIS Data Mining.','http://ereport.nogcc.ne.gov/');
INSERT INTO authority_scopes VALUES ('scope_19','body_nogcc','oil_gas','eReports site handles Production, Injection, Disposal; registration activation required; historic data through GIS Data Mining.');
INSERT INTO regulatory_bodies VALUES ('body_danr','DANR','South Dakota DANR Minerals and Mining Oil & Gas','jur_southdakota','Downloadable/fillable PDFs; mail correspondence/permit applications/reports','Forms are PDF/fillable PDF; Form 5 monthly production; UIC permit for injection; fillable PDFs should be downloaded and completed in Adobe Reader.','https://danr.sd.gov/Environment/MineralsMining/OilGas/OilGasForms.aspx');
INSERT INTO authority_scopes VALUES ('scope_20','body_danr','oil_gas','Forms are PDF/fillable PDF; Form 5 monthly production; UIC permit for injection; fillable PDFs should be downloaded and completed in Adobe Reader.');
INSERT INTO regulatory_bodies VALUES ('body_kdog','KDOG','Kentucky Division of Oil and Gas','jur_kentucky','Forms library; electronic spreadsheet for >10 wells; paper filings/fees','OG-17 annual monthly production due Apr 15; OG-18 annual disposal/injection due Jan 28; >10 wells require electronic spreadsheet from office.','https://eec.ky.gov/Natural-Resources/Oil-and-Gas/Pages/default.aspx');
INSERT INTO authority_scopes VALUES ('scope_21','body_kdog','oil_gas','OG-17 annual monthly production due Apr 15; OG-18 annual disposal/injection due Jan 28; >10 wells require electronic spreadsheet from office.');
INSERT INTO regulatory_bodies VALUES ('body_asogb','ASOGB','Alabama State Oil and Gas Board','jur_alabama','Forms/rules via ASOGB; state board filing workflows','State-specific ASOGB forms/rules should be checked directly; include permits, completion, production, injection, plugging and transfer workflows.','https://www.ogb.state.al.us/');
INSERT INTO authority_scopes VALUES ('scope_22','body_asogb','oil_gas','State-specific ASOGB forms/rules should be checked directly; include permits, completion, production, injection, plugging and transfer workflows.');
INSERT INTO regulatory_bodies VALUES ('body_tdec','TDEC','TDEC Division of Mineral & Geologic Resources Oil & Gas Program','jur_tennessee','Permit forms and TDEC program forms; paper/email per program instructions','Application to drill uses CN-0211 plus fee, plat, org report, surface owner certification, pooling affidavit, reclamation/action plan, bond.','https://www.tn.gov/environment/permits/mineral-geologic/oil-gas.html');
INSERT INTO authority_scopes VALUES ('scope_23','body_tdec','oil_gas','Application to drill uses CN-0211 plus fee, plat, org report, surface owner certification, pooling affidavit, reclamation/action plan, bond.');
INSERT INTO regulatory_bodies VALUES ('body_nysdec','NYSDEC','NYSDEC Division of Mineral Resources','jur_newyork','Email for e-signature forms; mail original annual report; NYeForm for production','Annual production due Mar 31; Annual Well Report original by mail or NYeForm; eSign forms must be emailed and not printed/mailed.','https://dec.ny.gov/environmental-protection/oil-gas/regulatory-program-forms');
INSERT INTO authority_scopes VALUES ('scope_24','body_nysdec','oil_gas','Annual production due Mar 31; Annual Well Report original by mail or NYeForm; eSign forms must be emailed and not printed/mailed.');
INSERT INTO regulatory_bodies VALUES ('body_fdep','FDEP','Florida DEP Oil and Gas Program','jur_florida','DEP forms and Business Portal; permit forms PDFs','Forms 1-16 for well permitting/production/injection/transport; geophysical Forms 1,4,5,5A,7; permit authority under Ch.377/62C-25 through 30.','https://floridadep.gov/water/oil-gas/content/forms');
INSERT INTO authority_scopes VALUES ('scope_25','body_fdep','oil_gas','Forms 1-16 for well permitting/production/injection/transport; geophysical Forms 1,4,5,5A,7; permit authority under Ch.377/62C-25 through 30.');
INSERT INTO regulatory_bodies VALUES ('body_modnr','MoDNR','Missouri Department of Natural Resources / Geological Survey','jur_missouri','PDF fill forms; permits/forms via DNR forms search','Commercial operator license, permit to drill/modify, monthly well status production/disposal, completion/recompletion/log, annual inventory, injection/MIT reports.','https://dnr.mo.gov/land-geology/businesses-landowners-permittees/permits/oil-gas');
INSERT INTO authority_scopes VALUES ('scope_26','body_modnr','oil_gas','Commercial operator license, permit to drill/modify, monthly well status production/disposal, completion/recompletion/log, annual inventory, injection/MIT reports.');
INSERT INTO regulatory_bodies VALUES ('body_azogcc','AZOGCC','Arizona Oil & Gas Conservation Commission','jur_arizona','Hard copy or email for APD; downloadable forms/checklists','Form 3 APD accepts one hard copy by mail or one electronic copy by email; requires Form 1, bond, fee, construction plan, plat, access/mineral-rights evidence.','https://azogcc.az.gov/forms');
INSERT INTO authority_scopes VALUES ('scope_27','body_azogcc','oil_gas','Form 3 APD accepts one hard copy by mail or one electronic copy by email; requires Form 1, bond, fee, construction plan, plat, access/mineral-rights evidence.');
INSERT INTO reporting_forms VALUES ('form_001','body_rrc','W-1','Application for Permit to Drill, Recomplete, or Re-Enter','Application for Permit to Drill, Recomplete, or Re-Enter','RRC Online available','Online filing / RRC form','Include drilling, recompletion/re-entry details; W-1H for horizontal and W-1D for directional supplemental information.','https://www.rrc.texas.gov/oil-and-gas/oil-and-gas-forms/');
