INSERT INTO reporting_forms VALUES ('form_003','body_rrc','PR','Monthly Production Report','Monthly Production Report','Online filing available; EDI filing requirements','Online/EDI','Monthly production report; stacked lateral production has PR instructions and EDI requirements.','https://www.rrc.texas.gov/oil-and-gas/oil-and-gas-forms/');
INSERT INTO reporting_requirements VALUES ('req_003','body_rrc','form_003','RRC PR — Monthly Production Report','monthly','Monthly','oil_gas','src_reg_matrix');
INSERT INTO citations VALUES ('cit_form_003','src_reg_matrix','reporting_form','form_003','Reg Reporting sheet — RRC PR');
INSERT INTO reporting_forms VALUES ('form_004','body_rrc','W-3 / W-3A','Plugging record / notice of intent to plug','Plugging record / notice of intent to plug','Online filing available','Online or fillable PDF','W-3 is plugging record; W-3A notice of intention to plug and abandon.','https://www.rrc.texas.gov/oil-and-gas/oil-and-gas-forms/');
INSERT INTO reporting_requirements VALUES ('req_004','body_rrc','form_004','RRC W-3 / W-3A — Plugging record / notice of intent to plug','event','Before and after plugging','oil_gas','src_reg_matrix');
INSERT INTO citations VALUES ('cit_form_004','src_reg_matrix','reporting_form','form_004','Reg Reporting sheet — RRC W-3 / W-3A');
